SELECT
    cc.id,
    cc.id_caja,
    cc.id_empresa,
    cc.id_empresa_cuenta_bancaria,
    cc.fecha_apertura,
    cc.fecha_cierre,
    cc.total_recaudado,
    cc.saldo_actual,
    cc.salida
FROM public.tb_caja_operativa_cierre cc
WHERE cc.id_caja = 23
ORDER BY cc.fecha_cierre;
