SELECT
    cc.id,
    cc.id_caja,
    cc.id_empresa,
    e.nombre AS empresa,
    cc.id_empresa_cuenta_bancaria,
    b.nombre AS banco,
    cc.fecha_apertura,
    cc.fecha_cierre
FROM public.tb_caja_operativa_cierre cc
JOIN public.tb_empresa e
  ON e.id = cc.id_empresa
JOIN public.tb_empresa_cuenta_bancaria ecb
  ON ecb.id = cc.id_empresa_cuenta_bancaria
JOIN public.tb_banco b
  ON b.id = ecb.id_banco
WHERE cc.id IN (50, 105, 192, 202)
ORDER BY cc.id;
