SELECT
    op.id,
    op.codigo_operacion_deposito_cliente,
    op.fecha_registro,
    op.fecha_deposito_cliente,
    op.id_empresa_ingreso,
    op.id_empresa_cuenta_ingreso,
    op.id_empresa_salida,
    op.id_empresa_cuenta_salida,
    op.id_caja_cierre,
    op.id_caja_cierre_ingreso,
    op.id_caja_cierre_salida
FROM public.tb_operacion_proceso op
WHERE op.id_empresa_ingreso = 14
  AND op.id_empresa_cuenta_ingreso = 24
  AND LOWER(COALESCE(op.ruta_origen, '')) = 'safetypay'
  AND op.id_caja_cierre_ingreso IS NULL
  AND UPPER(COALESCE(op.nombre_estado, '')) <> 'ELIMINADO'
ORDER BY op.fecha_registro, op.id;

