SELECT
    op.id AS id_operacion,
    op.fecha_registro,
    cierre.id AS cierre_safetypay,
    cierre.fecha_apertura,
    cierre.fecha_cierre
FROM public.tb_operacion_proceso op
LEFT JOIN LATERAL (
    SELECT cc.*
    FROM public.tb_caja_operativa_cierre cc
    WHERE cc.id_caja = 23
      AND op.fecha_registro >= cc.fecha_apertura
      AND op.fecha_registro < cc.fecha_cierre
    ORDER BY cc.fecha_cierre
    LIMIT 1
) cierre ON true
WHERE op.id_empresa_ingreso = 14
  AND op.id_empresa_cuenta_ingreso = 24
  AND LOWER(COALESCE(op.ruta_origen, '')) = 'safetypay'
